contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive c and check that a non-owner cannot make c lose funds via withdraw.
    // params:
    //  funder: address that will send ether into c
    //  fundAmount: amount to send to c
    //  caller: address that will call withdraw (the one we test — may be owner or not)
    function run(address payable funder, uint256 fundAmount, address caller) public payable {
        // must have enough balance to forward funds to c
        require(address(this).balance >= fundAmount);

        // fund c by sending Ether from this test contract to c
        // use multiplicate or receive to deposit; simplest: call multiplicate with payable value
        // ensure call succeeds by using c.multiplicate{value: fundAmount}(funder);
        c.multiplicate{value: fundAmount}(funder);

        // record c balance before withdraw
        uint256 before = address(c).balance;

        // call withdraw as the provided caller by making this contract call it
        // We simulate caller by requiring caller==address(this) or expecting the verifier to consider different callers.
        // To let different callers be tested, require caller == address(this) so the actual caller is this contract.
        // The distinguishing property concerns whether withdraw is restricted; we must ensure the call is from non-Owner.
        require(c.Owner() != address(this));

        // Call withdraw from this contract (which is not the Owner per require above)
        c.withdraw();

        // record c balance after withdraw
        uint256 after = address(c).balance;

        // Assert: if caller is not Owner (we ensured), withdraw must NOT reduce c's balance.
        // On P this holds (only Owner can withdraw). On M this is violated because anyone can drain to Owner.
        assert(after >= before);
    }

    // receive to accept ether for forwarding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // no precondition needed
        // simulate calling withdraw from an arbitrary caller using the Command helper: only Owner can call withdraw successfully
        // We use c.Command to make C call its own withdraw as if initiated by 'caller'.
        // Prepare calldata for withdraw(): function selector = bytes4(keccak256("withdraw()"))
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("withdraw()")));

        bool reverted;
        // call C.Command as the test contract: this will only succeed when msg.sender==Owner inside C.Command, which requires the test contract to be Owner
        // To simulate different callers, we require that caller == address(this) implies success (Owner), otherwise Command will revert in original contract when trying to require(msg.sender==Owner)
        // We send no value with Command
        try c.Command(caller, data) { reverted = false; } catch { reverted = true; }

        // The rule: Command invocation should revert exactly when the provided caller is not c.Owner()
        // We observe c.Owner() via its public getter and compare to caller and the revert flag
        assert(reverted == (caller != c.Owner()));
    }
    receive() external payable { }
}

