pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: an address attackerAddr (will be used to deploy adversary) and an amount
    function testFuzz_property(address attackerAddr, uint256 amount) public {
        // keep amount reasonable but allow wide range
        amount = bound(amount, 0, 1 ether);

        // fund an external account that will act as Owner challenger / adversary
        address payable depositor = payable(address(this));
        vm.deal(address(this), 2 ether);

        // deposit some Ether into c so withdraw has a balance to transfer
        uint256 deposit = 1 ether;
        vm.prank(address(this));
        c.Command{value: deposit}(address(this), ""); // harmless call, sends funds to contract via Command

        // sanity: contract has balance
        assert(address(c).balance == deposit);

        // Deploy an adversarial helper at a deterministic address by creating from attackerAddr as signer
        // We cannot control CREATE2 easily here; instead just deploy and use its address (attackerAddr parameter is unused as EOA)
        Adversary adv = new Adversary(address(c));

        // Fund the adversary so it can call Command with value if needed
        vm.deal(address(adv), amount);

        // Now drive c through Command such that the adversary's fallback will attempt to invoke withdraw on c.
        // We call Command with target = address(adv) so c will execute adv.call{value:msg.value}(data)

        // Make the call from adversary: prank the adversary to call c.Command so msg.sender inside Command is adv (not Owner)
        vm.prank(address(adv));
        try c.Command{value: 0}(address(adv), abi.encodeWithSignature("poke()")) {
            // nothing
        } catch {
            // ignore
        }

        // GENERAL ASSERTION: In the reference contract, only Owner can cause withdraw() to execute successfully; therefore after adversary-driven Command, the contract balance must remain owned/held (i.e., address(c).balance is unchanged or nonzero) unless Owner legitimately withdrew.
        // The mutant that removed the require allows anyone to call withdraw() and drain funds to Owner, so for some adversary behavior the balance would be reduced to 0. We assert that balance is still equal to deposit (no drain occurred).
        assertTrue(address(c).balance == deposit);
    }
}

// Minimal adversary: when called, it attempts to call withdraw() on the target contract c.
contract Adversary {
    address target;
    constructor(address _target) payable {
        target = _target;
    }
    // fallback is invoked when C.call executes into this contract; try to call withdraw on target
    fallback() external payable {
        // attempt to call withdraw on target
        (bool ok, ) = target.call(abi.encodeWithSignature("withdraw()"));
        // ignore result
        ok;
    }
    function poke() external {}
}

