pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: caller who will invoke Command, and an amount of wei to send to Command
    function testFuzz_property(address caller, uint256 sendAmount) public {
        // keep fuzzed values wide but sensible
        vm.assume(caller != address(0)); // non-zero address
        // bound sendAmount to an affordably large but practical range
        sendAmount = bound(sendAmount, 0, 1 ether);

        // fund caller so it can send ETH via Command
        vm.deal(caller, sendAmount + 1 ether);
        // fund the contract with some initial balance so withdraw has something to send
        vm.deal(address(this), 2 ether);
        // send 0.5 ether into c from this test contract
        payable(address(c)).transfer(0.5 ether);

        // Deploy a malicious helper that, when called by C via Command, will call c.withdraw().
        // This represents an adversarial callee that instructs C to perform withdraw() during Command.
        AttackerHelper atk = new AttackerHelper(c);

        // craft calldata to invoke the helper's trigger which will call c.withdraw() when C calls it
        bytes memory data = abi.encodeWithSelector(AttackerHelper.trigger.selector);

        // record contract balance before invoking Command
        uint256 beforeBal = address(c).balance;

        // Have the fuzzed caller invoke c.Command(attacker, data) sending sendAmount wei
        vm.prank(caller);
        // ensure caller has funds (vm.deal above)
        // call c.Command with value
        (bool ok, ) = address(c).call{value: sendAmount}(abi.encodeWithSelector(c.Command.selector, address(atk), data));
        // The reference C requires withdraw to be called only by Owner, so even if the helper calls c.withdraw(),
        // that withdraw call will revert when invoked by the helper (not Owner) and so no funds leave c.
        // The mutant removes that require, so the helper's call to withdraw will succeed and drain funds to Owner,
        // changing address(c).balance.

        // single assertion: after the above sequence, in the correct contract the balance must be unchanged by a non-Owner external attempt
        // (i.e., calling Command that causes a helper to attempt withdraw does not decrease c balance). We assert that the
        // contract balance is equal to the recorded beforeBal (the reference preserves this for all inputs; the mutant is able to lower it).
        assertTrue(address(c).balance == beforeBal);
    }
}

// Minimal adversarial helper: when invoked, it calls back into c.withdraw()
contract AttackerHelper {
    C public c;
    constructor(C _c) payable { c = _c; }
    // Called by C via Command; when executed, this will call c.withdraw()
    function trigger() external payable {
        // try to call withdraw; in the reference this will revert because msg.sender != Owner
        // in the mutant this will succeed and drain funds to Owner
        // Use low-level call to propagate success/failure to C context
        (bool s, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector));
        // swallow return to avoid bubbling; behavior (success vs failure) is what matters
    }
}

