pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an attacker address (will be funded) and an amount of Ether supplied to Command
    function testFuzz_property(address attacker, uint256 value) public {
        // keep domain wide but sensible: non-zero attacker and a bounded value to avoid overflow in vm.deal
        vm.assume(attacker != address(0));
        value = bound(value, 0, 1 ether);

        // Deploy a malicious callee that, when Command calls it, will attempt to call c.withdraw()
        MaliciousCallee mal = new MaliciousCallee(address(c));

        // Fund the contract c so there is something to withdraw
        // Fund Owner as well to allow Owner interactions if needed
        address owner = address(uint160(uint256(keccak256(abi.encodePacked("ownerseed")))));
        vm.deal(address(c), 1 ether);

        // Fund attacker so it can call Command with value
        vm.deal(attacker, value);

        // Attacker calls Command targeting the malicious callee, forwarding `value` wei
        vm.prank(attacker);
        // Prepare empty data; the malicious callee's fallback will execute
        bytes memory data = "";
        // Call Command; it will in turn call the malicious callee, which will attempt to call c.withdraw()
        // We capture whether Command succeeded or reverted to observe behaviors, but our invariant will check balance
        bool ok;
        try c.Command{value: value}(address(mal), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: after this interaction, only the Owner can have caused c to transfer out its balance via withdraw.
        // Observationally: for the correct contract, a non-Owner attacker's Call to Command (even if it triggers a callee that calls back into c.withdraw)
        // must NOT reduce address(c).balance to 0 — withdraw can only succeed when msg.sender == Owner, so attacker-triggered attempts fail.
        // Therefore, for all attacker and value, address(c).balance must remain >= (original balance - 0) and specifically must NOT become 0 purely by attacker-triggered Command.
        // We assert that address(c).balance is strictly greater than 0 after the attack (since we seeded it with 1 ether), which holds for the reference
        // but will fail for the mutant where anyone can call withdraw.
        assertTrue(address(c).balance > 0);
    }
}

// Malicious callee: whenever it receives a call it will try to call c.withdraw() (as msg.sender = this contract),
// which in the mutant will succeed (draining funds to Owner) but in the reference will revert due to require(msg.sender == Owner).
contract MaliciousCallee {
    C target;
    constructor(address _t) { target = C(_t); }
    fallback() external payable {
        // Attempt to call withdraw on the target. This will succeed on the mutant (since withdraw no longer checks sender)
        // and revert on the reference (require(msg.sender == Owner)). We don't catch revert here; Command will observe it.
        // Use low-level call to avoid bubbling reverts here and let Command's try/catch observe results; however per instructions
        // we only need the callee to attempt the call (which may revert or succeed depending on target).
        // We perform a low-level call to avoid revert propagation out of this fallback (so Command's call can continue to return)
        // but we also attempt a direct call to observe the draining in the mutant. Use try/catch to swallow revert locally.
        try target.withdraw{value: 0}() {
            // no-op
        } catch {
            // swallow
        }
    }
}

