pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attacker address and an ETH amount to send to Command
    function testFuzz_property(address attacker, uint256 amt) public {
        // keep amount reasonable and non-zero to have funds in contract and to send
        amt = bound(amt, 1, 1 ether);

        // fund attacker so it can send ETH in Command
        vm.deal(attacker, amt);

        // Deploy a malicious callee that, when called by c, will call c.withdraw()
        // This models an external party that causes c to execute withdraw() from its own context.
        MaliciousCallee mal = new MaliciousCallee(c);

        // Owner is c.Owner() (the deployer of c in setUp)
        address owner = c.Owner();

        // Ensure attacker is not the Owner to allow distinguishing behavior
        vm.assume(attacker != owner);

        // Record balance before
        uint256 before = address(c).balance;

        // Give the contract some initial funds so withdraw can drain something
        // Send 0.5 ether from owner to c
        vm.deal(owner, 0.5 ether);
        vm.prank(owner);
        (bool s, ) = payable(address(c)).call{value: 0.5 ether}("");
        require(s);

        // sanity: contract has positive balance now
        before = address(c).balance;
        require(before > 0);

        // From attacker, call Command with the malicious callee address so that c will low-level-call mal
        bytes memory data = abi.encodeWithSelector(MaliciousCallee.poke.selector);

        vm.prank(attacker);
        // attacker sends amt along with the Command call
        // wrap in try/catch to allow both reference and mutant behaviors (some may revert)
        bool ok;
        try c.Command{value: amt}(address(mal), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the Command completes, the reference contract ensures only Owner can successfully call withdraw(),
        // so the contract balance must remain >= 0 and specifically, for the reference, a non-Owner-caused drain cannot have occurred.
        // The distinguishing observable: for all inputs the reference preserves that balance stays >= 0 and cannot be drained by non-Owner via this interaction.
        // We assert that either the balance is unchanged (>= some minimal value) or that the call reverted; the mutant (removed require)
        // will allow the malicious callee to trigger withdraw() and drain the contract to Owner, making address(c).balance == 0 for some inputs.

        // General property (single assert): The contract balance is never zero after this interaction when attacker != Owner.
        // On the reference this holds for all inputs because the malicious callee cannot cause withdraw() to succeed when called by non-Owner;
        // the mutant allows withdraw to succeed and for some fuzzed amt/attacker will make balance == 0, causing this assertion to fail.
        assertTrue(address(c).balance != 0);
    }
}

// Minimal malicious callee: when poked via Command, it will call back into c.withdraw()
contract MaliciousCallee {
    C c;
    constructor(C _c) { c = _c; }
    // callable entry for Command
    function poke() external payable {
        // attempt to call withdraw on C; if allowed (mutant) this will transfer funds out
        // ignore success/failure
        try c.withdraw() {
        } catch {
        }
    }
    // fallback to accept ETH when c.call sends value
    receive() external payable {}
}

