import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: attacker address (will be EOA simulated by vm.prank) and amount sent into Command
    function testFuzz_property(address attacker, uint256 sendAmt) public {
        // keep attacker non-zero and not the Owner to explore adversarial caller space
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this)); // avoid using the test contract as owner
        // wide bound on amount but cap to reasonable gas funding limits
        sendAmt = bound(sendAmt, 0, 1 ether);

        // Fund the contract so there is something to withdraw
        vm.deal(address(this), 1 ether);
        // send ether into contract via direct call to receive
        (bool ok,) = address(c).call{value: 0.5 ether}(""");
        require(ok);

        // Deploy a malicious callee which will, when called by c.Command, call back into c.withdraw().
        // This models an external counterparty that triggers withdraw from c during Command.
        ReenteringCaller attackerContract = new ReenteringCaller(c);

        // Fund attacker EOA so it can send value through Command
        vm.deal(attacker, sendAmt);

        // Have the attacker call c.Command with the malicious callee's address so that c executes a low-level call
        vm.prank(attacker);
        // craft calldata empty (irrelevant) — the attackerContract's fallback will perform the reentrant call
        try c.Command(address(attackerContract), "") {
            // command returned normally
        } catch {
            // if it reverts, treat as false outcome
        }

        // The invariant: only Owner can successfully invoke withdraw to transfer contract balance away.
        // On the correct contract, a non-Owner (attacker) cannot cause withdraw to run and drain the balance.
        // Therefore address(c).balance must remain > 0 for all admissible inputs where caller != Owner.
        // We assert that the contract still has a positive balance after the attempted attack by attacker.
        assertTrue(address(c).balance > 0);
    }
}

contract ReenteringCaller {
    C immutable target;
    constructor(C _t) payable { target = _t; }
    fallback() external payable {
        // attempt to call withdraw on target; if target has the require, this will revert and not drain funds.
        // If target is mutated to remove the require, this will succeed and drain its balance.
        // We ignore revert here to let test observe balance change.
        try target.withdraw{value: 0}() {
        } catch {}
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function containing all test logic
    // params: amount to fund C with, and an address 'attacker' used as msg.sender simulation via call
    // We cannot change msg.sender in Solidity, so we instead rely on the contract's behaviour when this contract calls withdraw.
    function run(uint256 fundAmount, address payable recipient) public {
        // ensure this contract has enough balance to fund C
        require(address(this).balance >= fundAmount);

        // Fund C by sending Ether using multiplicate in a way that increases C's balance.
        // Use payable call to multiplicate with value fundAmount.
        c.multiplicate{value: fundAmount}(recipient);

        // After funding, require that C now has nonzero balance (setup precondition)
        require(address(c).balance > 0);

        // Call withdraw from this contract (this contract is msg.sender for this call)
        // In the original contract, withdraw only allows Owner to withdraw; since this contract is not Owner (constructor of C set Owner elsewhere), this call should revert or do nothing that transfers funds out to Owner.
        // We call and capture success boolean to observe whether the call reverted.
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("withdraw()"));

        // If the original contract enforces require(msg.sender == Owner), this call must fail (revert) when sender is not Owner.
        // The mutant flips that to require(msg.sender != Owner) making this call succeed and cause the contract's balance to be transferred to Owner, leaving C balance = 0.
        // Assert that C's balance remains non-negative and, specifically, that it is NOT zero after our call (i.e., withdraw did not empty the contract when called by a non-owner).
        // This distinguishes original (withdraw by non-owner cannot empty balance) from mutant (withdraw by non-owner empties balance).
        assert(address(c).balance != 0);
    }

    // allow this contract to receive Ether for funding
    receive() external payable {}
}

