        // since we cannot read Owner, we express the property as: the call does not succeed for arbitrary caller,
        // so require that reverted == true (i.e., non-owner calls revert). To make it general, we assert reverted.

        // The intended rule: withdraw called by this contract (likely non-owner) must revert on P.
        assert(reverted);
    }
    receive() external payable {}
}

